/** A paisagem de um lugar: { chave, agua, ilustrativo } — `ilustrativo` só quando veio da base regional. */
export function paisagemDe(lugar) {
  const porLugar = CURADORIA.porLugar[lugar.i];
  if (porLugar) {
    const p = typeof porLugar === 'string' ? { paisagem: porLugar } : porLugar;
    return { chave: p.paisagem, agua: p.agua ?? PAISAGENS[p.paisagem].agua, ilustrativo: false };
  }
  const porMeso = lugar.m && CURADORIA.porMesorregiao[lugar.m];
  if (porMeso) return { chave: porMeso, agua: PAISAGENS[porMeso].agua, ilustrativo: false };
  const base = CURADORIA.porRegiao[lugar.r] ?? 'interior';
  return { chave: base, agua: PAISAGENS[base].agua, ilustrativo: true };
}


